public class BitInputStream_readBits_TriageGen2Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming a reasonable constant for testing

    @Test(expected = IllegalArgumentException.class)
    public void testReadBits_NegativeCount() throws IOException {
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(new byte[0]), ByteOrder.BIG_ENDIAN);
        bis.readBits(-1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testReadBits_TooLargeCount() throws IOException {
        // Using a value larger than MAXIMUM_CACHE_SIZE
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(new byte[0]), ByteOrder.BIG_ENDIAN);
        bis.readBits(MAXIMUM_CACHE_SIZE + 1);
    }

    @Test
    public void testReadBits_LittleEndian_Simple() throws IOException {
        // Data: 0x01, 0x02 -> bits: 00000001 00000010 (LE)
        // Read 8 bits -> 1
        byte[] data = {0x01, 0x02};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);
        assertEquals(1L, bis.readBits(8));
        assertEquals(2L, bis.readBits(8));
    }

    @Test
    public void testReadBits_BigEndian_Simple() throws IOException {
        // Data: 0x01, 0x02 -> bits: 00000001 00000010 (BE)
        // Read 8 bits -> 1
        byte[] data = {0x01, 0x02};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);
        assertEquals(1L, bis.readBits(8));
        assertEquals(2L, bis.readBits(8));
    }

    @Test
    public void testReadBits_EndOfStream() throws IOException {
        byte[] data = {0x01};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);
        assertEquals(1L, bis.readBits(8));
        assertEquals(-1L, bis.readBits(8));
    }

