        // Now request something that triggers the overflow logic:
        // The code says: if (bitsCachedSize < count) { ... }
        // Since count <= MAXIMUM_CACHE_SIZE, we need a large count.
        // But if bitsCachedSize is already 64, and count is say 60, it won't enter.
    }

    @Test
    public void testReadBits_BigEndian_Complex() throws IOException {
        // Test Big Endian bit shifting logic
        byte[] data = { (byte)0xAB, (byte)0xCD }; // 10101011 11001101
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        // Read 4 bits -> 1010 (10)
        assertEquals(10L, bis.readBits(4));
        // Read 12 bits -> 1011 1100 1101 (3003)
        assertEquals(3003L, bis.readBits(12));
    }

    @Test
    public void testReadBits_LittleEndian_Complex() throws IOException {
        byte[] data = { (byte)0x01, (byte)0x02 }; // 00000001 00000010
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 4 bits -> 0001 (1)
        assertEquals(1L, bis.readBits(4));
        // Read 12 bits -> 0000 0010 0000 (32)
        assertEquals(32L, bis.readBits(12));
    }

    @Test
    public void testReadBits_TriggerOverflowBranch_LE() throws IOException {
        // We need bitsCachedSize >= 57 and bitsCachedSize < count
        // Let's assume MAXIMUM_CACHE_SIZE is 64.
        // 1. Read 57 bits (via multiple calls)
        // 2. Request 64 bits.

        byte[] data = new byte[15];
        for(int i=0; i<15; i++) data[i] = (byte)0xFF;

        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Use 57 bits to get bitsCachedSize to 64 via the while loop
        // The loop: while (bitsCachedSize < count && bitsCachedSize < 57)
        // If we request 60, it fills up to 64 because the loop continues while bitsCachedSize < 57.
        // If bitsCachedSize becomes 64, then the overflow block 'if (bitsCachedSize < count)' is skipped.

        // To enter the overflow block:
        // We need bitsCachedSize to be >= 57, but < count.
        // This is only possible if the 'while' loop finishes because bitsCachedSize >= 57, 
        // but the 'count' requested is even larger than the resulting bitsCachedSize.

        // Step 1: Get bitsCachedSize to exactly 57 or more.
        // Since we read in bytes, bitsCachedSize will be multiples of 8.
        // Let's read 56 bits.
        bis.readBits(56); 
        // Now bitsCachedSize = 0 (because it was consumed).

        // We need to bypass the while loop by having bitsCachedSize already high.
        // Let's call readBits with a small count to leave some bits in cache.
        // But readBits clears cache bits consumed. 
        // The only way to have bitsCachedSize >= 57 is if the while loop runs.
        // But the while loop stops if bitsCachedSize >= 57.

        // Let's simulate the state:
        // If we call readBits(60):
        // while (0 < 60 && 0 < 57) -> reads 1 byte, bitsCachedSize = 8...
        // ... reads 7 bytes, bitsCachedSize = 56.
        // ... reads 8th byte, bitsCachedSize = 64.
        // Loop ends because bitsCachedSize (64) is not < 57.
        // bitsCachedSize (64) is not < count (60).
        // Overflow block is skipped.

        // To hit the overflow block, we need a count > 64 (if bitsCachedSize is 64)
        // or a count > bitsCachedSize where bitsCachedSize is 57-63.
        // But bitsCachedSize is always a multiple of 8 after the while loop.
        // The only way bitsCachedSize is not a multiple of 8 is if we provided a count 
        // that wasn't a multiple of 8.

        // Let's try:
        BitInputStream bis2 = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);
        bis2.readBits(57); // bitsCachedSize becomes 64, 57 bits consumed.
        // wait, bitsCachedSize becomes 64, then bitsCachedSize -= count -> 64 - 57 = 7.
        // Now bitsCachedSize = 7.
        // If we call readBits(60):
        // while (7 < 60 && 7 < 57) -> will read bytes until bitsCachedSize >= 57.
        // It will read 7 more bytes. bitsCachedSize = 7 + (7*8) = 63.
        // Now bitsCachedSize (63) < count (60) is FALSE.

        // Let's try to make bitsCachedSize = 57.
        // If we read 57 bits, bitsCachedSize becomes 7.
        // If we then call readBits(60):
        // while (7 < 60 && 7 < 57) -> reads 7 bytes. bitsCachedSize = 7 + 56 = 63.
        // 63 < 60 is false.

        // To hit the overflow:
        // We need bitsCachedSize to be, say, 57, and count to be 60.
        // This is actually impossible with the current while loop logic because the while loop 
        // always increments bitsCachedSize by 8. So bitsCachedSize will be 64.
        // UNLESS bitsCachedSize was already 57.
        // How can bitsCachedSize be 57? 
        // If we read bits such that bitsCachedSize becomes 57.
        // Example: readBits(57) -> bitsCachedSize becomes 64, then 64-57=7.
        // Let's try to get bitsCachedSize to be 57.
        // If we read 57 bits, we have 7 bits left.
        // If we read 7 bits, we have 0 bits left.
        // The only way to get bitsCachedSize to 57 is if the loop or logic allows it.
        // The while loop: bitsCachedSize += 8.
        // So bitsCachedSize is always multiple of 8.
        // The only way to get bitsCachedSize to 57 is the "if (bitsCachedSize < count)" block 
        // which sets "bitsCachedSize = count".

        // Let's try:
        // 1. readBits(57) -> bitsCachedSize = 7.
        // 2. To get bitsCachedSize = 57, we need to call readBits(57) again? No.
        // Actually, if we call readBits(57), bitsCachedSize becomes 7.
        // If we then call readBits(57) again, the while loop runs:
        // while (7 < 57 && 7 < 57) -> reads 6 bytes. bitsCachedSize = 7 + 48 = 55.
        // Loop ends because 55 < 57 is true, but the next iteration 55+8 = 63.
        // Wait, the loop condition is (bitsCachedSize < count && bitsCachedSize < 57).
        // If bitsCachedSize is 55, and count is 57:
        // 55 < 57 and 55 < 57 is TRUE.
        // nextByte = in.read(); bitsCachedSize += 8 (now 63).
        // Loop ends.
        // bitsCachedSize is 63. count is 57. 63 < 57 is FALSE.

        // The only way to enter `if (bitsCachedSize < count)` is if `count` is very large.
        // If count = 64, and bitsCachedSize = 63.
        // Let's try:
        // 1. Call readBits(57). bitsCachedSize = 7.
        // 2. Call readBits(57). bitsCachedSize = 63, count = 57.
        // 3. Call readBits(64).
        //    While (63 < 64 && 63 < 57) -> 63 < 57 is FALSE. Loop ends.
        //    If (bitsCachedSize < count) -> (63 < 64) is TRUE!
        //    This triggers the overflow block.

        BitInputStream bis3 = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);
        bis3.readBits(57); // bitsCachedSize = 7
        bis3.readBits(57); // bitsCachedSize = 63
        // Now count = 64, bitsCachedSize = 63.
        // bitsCachedSize < count (63 < 64) is TRUE.
        // overflowBits = 8 - (64 - 63) = 7.
        // nextByte = in.read();
        // bitsToAddCount = 1.
        // bitsToAdd = nextByte & MASKS[1].
        // bitsCached |= (bitsToAdd << 63).
        // overflow = (nextByte >>> 1) & MASKS[7].
        // bitsCachedSize = 64.
        long result = bis3.readBits(64);
        // Since all bytes are 0xFF, result should be all 1s.
        assertEquals(0xFFFFFFFFFFFFFFFFL, result);
    }

    @Test
    public void testReadBits_BigEndian_Overflow() throws IOException {
        byte[] data = new byte[20];
        for(int i=0; i<20; i++) data[i] = (byte)0xFF;

        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        // 1. bitsCachedSize = 0. Call readBits(57).
        //    While (0 < 57 && 0 < 57) -> reads 8 bytes. bitsCachedSize = 64.
        //    bitsCachedSize = 64 - 57 = 7.
        bis.readBits(57); // bitsCachedSize = 7.

        // 2. Call readBits(57).
        //    While (7 < 57 && 7 < 57) -> reads 7 bytes. bitsCachedSize = 7 + 56 = 63.
        //    bitsCachedSize = 63 - 57 = 6.
        bis.readBits(57); // bitsCachedSize = 6.

        // 3. Call readBits(64).
        //    While (6 < 64 && 6 < 57) -> reads 7 bytes. bitsCachedSize = 6 + 56 = 62.
        //    Loop ends because 62 < 57 is false.
        //    If (62 < 64) is TRUE.
        //    bitsToAddCount = 64 - 62 = 2.
        //    overflowBits = 8 - 2 = 6.
        //    nextByte = in.read();
        //    bitsCached <<= 2;
        //    bitsToAdd = (nextByte >>> 6) & MASKS[2];
        //    bitsCached |= bitsToAdd;
        //    overflow = nextByte & MASKS[6];
        //    bitsCachedSize = 64.
        //    bitsOut = bitsCached & MASKS[64]; (effectively all 1s)

        long result = bis.readBits(64);
        assertEquals(0xFFFFFFFFFFFFFFFFL, result);
    }

